// IndexedDB v2 preserves v1 images and adds reusable Vibes and named API profiles.
function openDB(){return new Promise((resolve,reject)=>{const r=W.indexedDB.open('pear-nai-'+state.scope,3);r.onupgradeneeded=()=>{for(const name of ['images','vault','vibes','metadata'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name,{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('本地存储不可用，请检查浏览器设置。'));r.onblocked=()=>notify('请关闭其他旧版画室页面，再刷新。',true);});}
const dbReady=openDB().then(async value=>{db=value;profiles=(await dbOp('vault','getAll')).filter(p=>p.kind==='api');vibes=(await dbOp('vibes','getAll')).filter(x=>!s.deletedVibeGroups.includes(x.id));refreshProfiles();assets=(await dbOp('vault','get','draw-assets'))?.value||assets;renderAssets();renderBalance();await renderVibes();if(dead)db.close();}).catch(err=>notify(err.message,true));
