async function api(path,payload,profile){profile??=activeProfile();let r;try{r=await W.fetch(endpointBase(profile.url,profile.type)+path,{method:payload===null?'GET':'POST',headers:{Authorization:'Bearer '+profile.key,'Content-Type':'application/json',Accept:'application/json'},...(payload===null?{}:{body:JSON.stringify(payload)}),signal:controller?.signal,redirect:'error'});}catch(err){if(err.name==='AbortError')throw err;throw Error('接口连接失败，请检查网址、网络和跨域支持。');}if(!r.ok)throw Error(`接口返回 ${r.status}，请检查 Key、余额或参数。`);return r;}
