async function restoreSettings(backup){
 if(busy||generationActive||waitCount)throw Error('请等待当前任务结束。');
 const restored=Backup.merge(backup,s,profiles);
 await new Promise((resolve,reject)=>{const tx=db.transaction(backup.vibes?['vault','vibes']:['vault'],'readwrite');let error;tx.onabort=tx.onerror=()=>reject(error||Error('导入失败，原设置已保留。'));tx.oncomplete=resolve;try{const vault=tx.objectStore('vault');for(const p of profiles)vault.delete(p.id);for(const p of restored.profiles)vault.put(p);if(backup.assets)vault.put({id:'draw-assets',value:backup.assets});if(backup.vibes){const store=tx.objectStore('vibes');store.clear();for(const v of backup.vibes)store.put(v);}}catch(err){error=err;tx.abort();}});
 state.studio2=restored.settings;save();
}

