async function refreshBalance(){await dbReady;const profile=activeProfile();if(profile.type==='third'){renderBalance();return;}balanceBadge.classList.add('waiting');try{const data=await(await api('/user/subscription',null,profile)).json(),steps=data.trainingStepsLeft;if(!steps||!Number.isFinite(steps.fixedTrainingStepsLeft)||!Number.isFinite(steps.purchasedTrainingSteps))throw Error('接口没有返回可识别的点数。');const p=profiles.find(x=>x.id===profile.id);if(!p)return;p.balance={remaining:steps.fixedTrainingStepsLeft+steps.purchasedTrainingSteps,fixed:steps.fixedTrainingStepsLeft,purchased:steps.purchasedTrainingSteps,time:Date.now(),manual:false,usage:data.usage||null,sub:{tier:data.tier??null,active:!!data.active,expiresAt:Number(data.expiresAt)||0}};await dbOp('vault','put',p);renderBalance();}finally{balanceBadge.classList.remove('waiting');}}
function subShort(sub){if(!sub)return'';if(!sub.active||!sub.expiresAt)return'会员未开通';const end=new Date(sub.expiresAt*1000),days=Math.floor((end-Date.now())/86400000);return'到期 '+(end.getMonth()+1)+'/'+end.getDate()+(days>=0?' · 剩'+days+'天':' · 已过期');}
function subText(sub){if(!sub)return'';const tier=['Paper','Tablet','Scroll','Opus'][sub.tier]||'';if(!sub.active||!sub.expiresAt)return tier&&sub.tier>0?tier+' · 未生效':'会员未开通';const end=new Date(sub.expiresAt*1000),days=Math.floor((end-Date.now())/86400000),pad=n=>String(n).padStart(2,'0');return(tier?tier+' · ':'')+'到期 '+end.getFullYear()+'-'+pad(end.getMonth()+1)+'-'+pad(end.getDate())+(days>=0?'（剩 '+days+' 天）':'（已过期）');}
