async function accountGeneration(profile,amount){const current=profiles.find(x=>x.id===profile.id);if(!current)return;if(profile.type==='third'&&current.balance?.manual){current.balance.remaining=Number((current.balance.remaining-current.balance.cost*amount).toFixed(6));await dbOp('vault','put',current);renderBalance();}else if(profile.type==='official'&&s.activeApi===profile.id){try{await refreshBalance();}catch{notify('图片已生成，余额刷新失败；显示上次余额。');}}}
