// Read-only parsing helpers; no worldbook writes, tag injection, or extra LLM.
function extract(str,start,end,max=20){const out=[];let at=0;while(out.length<max){const a=String(str).indexOf(start,at);if(a<0)break;const z=String(str).indexOf(end,a+start.length);if(z<0)break;const value=String(str).slice(a+start.length,z).trim();if(value)out.push(value);at=z+end.length;}return out;}
function parseScene(value){if(value.trim().startsWith('{')){const x=JSON.parse(value);if(typeof x.prompt!=='string')throw Error('绘图标签缺少 prompt。');return{prompt:x.prompt,negative:typeof x.negative==='string'?x.negative:'',characters:validateCharacters(x.characters||[]),coords:!!x.coords};}return{prompt:value,negative:'',characters:[],coords:false};}
// image### grammar: only labelled English prompt fields enter the request.
function gridCenter(value){const m=/^([A-E])([1-5])$/i.exec(value.trim());if(!m)throw Error('无法识别角色位置：'+value+'（支持 A1–E5，C3 为中央）');return{x:(m[1].toUpperCase().charCodeAt(0)-65)/4,y:(Number(m[2])-1)/4};}
function parseImageBlock(str){
 const markers=[...str.matchAll(/(?:^|;)\s*(Scene Composition|Scene UC|Negative Prompt|Character\s+(\d+)\s+(Prompt|UC))\s*:/gi)];
 if(!markers.length)throw Error('image### 缺少 Scene Composition 字段。');
 const result={prompt:'',negative:'',characters:[],coords:false},characters=new Map(),fields=new Set();
 for(let i=0;i<markers.length;i++){const m=markers[i],label=m[1].toLowerCase().replace(/\s+/g,' ');if(fields.has(label))throw Error('重复字段：'+m[1]);fields.add(label);let value=str.slice(m.index+m[0].length,markers[i+1]?.index??str.length).trim().replace(/;\s*$/,'').trim();if(/[<>]/.test(value))throw Error('绘图字段包含 HTML 或思考标签，请检查原文。');
 if(label==='scene composition'){result.prompt=value;continue;}if(label==='scene uc'||label==='negative prompt'){result.negative=value;continue;}
 const id=Number(m[2]);if(!Number.isInteger(id)||id<1||id>22)throw Error('角色编号须为 1–22。');const c=characters.get(id)||{prompt:'',negative:'',x:.5,y:.5};
 if(m[3].toLowerCase()==='prompt'){const position=/\|\s*centers\s*:\s*([^;|]+)\s*$/i.exec(value);if(position){Object.assign(c,gridCenter(position[1]));result.coords=true;value=value.slice(0,position.index).trim();}c.prompt=value;}else c.negative=value;characters.set(id,c);
 }
 if(!result.prompt)throw Error('场景提示词不能为空。');result.characters=[...characters.entries()].sort((a,b)=>a[0]-b[0]).map(([id,c])=>{if(!c.prompt)throw Error('角色 '+id+' 缺少 Prompt。');return c;});return result;
}
function messageScenes(raw){const cleaned=String(raw).replace(/<tag_think\b[^>]*>[\s\S]*?<\/tag_think\s*>/gi,'');const results=[];const blocks=/image###([\s\S]*?)###/gi;let m;while((m=blocks.exec(cleaned))){if(results.length>=20)throw Error('单层绘图块超过 20 个。');try{results.push(parseImageBlock(m[1]));}catch{results.push(null);}}if(results.length)return results;return extract(cleaned,'<nai>','</nai>').map(value=>{try{return parseScene(value);}catch{return null;}});}
// PNG text chunks and NovelAI alpha-LSB stealth metadata are decoded locally.
const META_LIMIT=8*1024*1024;
async function inflateLimited(bytes,format){if(!W.DecompressionStream)throw Error('浏览器不支持压缩元数据解码，请升级浏览器。');const reader=new Blob([bytes]).stream().pipeThrough(new W.DecompressionStream(format)).getReader();let total=0,chunks=[];try{while(true){const r=await reader.read();if(r.done)break;total+=r.value.length;if(total>META_LIMIT)throw Error('元数据解压后过大。');chunks.push(r.value);}}finally{await reader.cancel().catch(()=>{});}const out=new Uint8Array(total);let at=0;for(const part of chunks){out.set(part,at);at+=part.length;}return out;}
