const metadataLibraryFlags={};const metadataLibraryOptions=e('div',undefined,'row');for(const [key,label]of [['prompt','正面'],['negative','负面'],['characters','人物'],['settings','参数及模型'],['seed','种子'],['vibes','Vibe']]){const tick=e('input');tick.type='checkbox';tick.checked=true;metadataLibraryFlags[key]=tick;metadataLibraryOptions.append(field(label,tick));}
pages['元数据库'].append(uploadButton('上传原图并存储元数据',files=>withWait(async()=>{for(const file of files){const parsed=await extractMetadata(file),embedded=await resolveMetadataVibes(parsed.raw),data=normalizeMetadata(parsed.raw);data.vibes=embedded.items;await dbReady;await dbOp('metadata','put',{id:uid(),name:file.name,time:Date.now(),data,image:'data:image/png;base64,'+await blobBase64(file),tags:[],favorite:false,warnings:[...parsed.warnings,...embedded.warnings]});}await renderMetadataLibrary();notify('元数据已保存；Vibe 未加入库。');}),'image/png',true),metadataSearch,metadataLibraryOptions,metadataLibraryList);
function selectedMetadata(data){return Object.fromEntries(Object.entries(metadataLibraryFlags).filter(([k,c])=>c.checked&&data[k]!==undefined).map(([k])=>[k,data[k]]));}
let metadataFavoritesOnly=false,metadataTagFilter='';
const metadataFilterRow=e('div',undefined,'row'),metadataFavoriteToggle=b('全部图片',()=>{metadataFavoritesOnly=!metadataFavoritesOnly;metadataFavoriteToggle.textContent=metadataFavoritesOnly?'只看收藏':'全部图片';return renderMetadataLibrary();}),metadataTagInput=text('');metadataTagInput.placeholder='按标签筛选';metadataTagInput.oninput=()=>{metadataTagFilter=metadataTagInput.value.trim().toLowerCase();guard(renderMetadataLibrary)();};metadataFilterRow.append(metadataFavoriteToggle,metadataTagInput);pages['元数据库'].insertBefore(metadataFilterRow,metadataLibraryList);metadataLibraryList.className='gallery metadata-gallery';
safetyStyle.textContent+=' .metadata-gallery .metadata-library-card{min-width:0;position:relative;margin:0;overflow-wrap:anywhere}.metadata-gallery img{width:100%;height:200px;object-fit:contain;cursor:pointer}.metadata-gallery .row button{padding:7px 4px;font-size:12px}.metadata-gallery .meta-tags{font-size:12px;opacity:.75}.metadata-upload{display:block;width:100%}.metadata-upload button{width:100%}.metadata-gallery .meta-missing{height:200px;display:grid;place-items:center;border:1px dashed currentColor}.inline-preview-rail{width:100%;min-width:0}.viewer-grid>div{min-width:0}';pages['元数据库'].firstElementChild.classList.add('metadata-upload');
async function updateMetadataEntry(id,patch){const fresh=await dbOp('metadata','get',id);if(!fresh)throw Error('此元数据已删除。');Object.assign(fresh,patch);await dbOp('metadata','put',fresh);await renderMetadataLibrary();return fresh;}
function editMetadataEntry(item){const {dialog,close}=modal('名称与标签'),name=text(item.name),tags=text((item.tags||[]).join(', '));dialog.append(field('元数据图的名字',name),field('标签（逗号分隔）',tags),b('保存',async()=>{if(!name.value.trim())throw Error('请填写名字。');await updateMetadataEntry(item.id,{name:name.value.trim().slice(0,150),tags:[...new Set(tags.value.split(/[,，\n]/).map(v=>v.trim()).filter(Boolean))].slice(0,30)});close();}));}
function metadataImageViewer(item){const {dialog,close}=modal(item.name);dialog.classList.add('viewer');const grid=e('div',undefined,'viewer-grid'),im=e('img',undefined,'viewer-image'),info=e('div',undefined,'viewer-info');im.src=item.image;im.alt=item.name;im.onclick=()=>imagePreview(item.image);for(const[key,label]of [['prompt','正面'],['negative','负面'],['characters','人物'],['settings','参数及模型'],['seed','种子']])if(item.data[key]!==undefined){const box=section(info,label,key==='prompt'),value=typeof item.data[key]==='string'?item.data[key]:JSON.stringify(item.data[key],null,2);box.append(e('pre',value),b('复制',()=>copyText(value)));}note(info,'Vibe：'+(item.data.vibes?.length||0)+' 个');info.append(row(b('复制所选数据',()=>copyMetadataSelection(item)),b('抓取 / 导入',()=>showMetadata(copy(item.data),item.warnings||[],close))),row(b('名称与标签',()=>editMetadataEntry(item)),b(item.favorite?'取消收藏':'收藏',async()=>{item=await updateMetadataEntry(item.id,{favorite:!item.favorite});notify(item.favorite?'已收藏':'已取消收藏');})));grid.append(im,info);dialog.append(grid);}
async function copyMetadataSelection(item){const data=selectedMetadata(item.data);if(!Object.keys(data).length)throw Error('请先勾选要复制的数据。');await copyText(JSON.stringify(data,null,2));notify('已复制所选元数据。');}
async function renderMetadataLibrary(){await dbReady;const all=await dbOp('metadata','getAll');metadataLibraryList.replaceChildren();for(const item of all.sort((a,b)=>b.time-a.time).filter(x=>x.name.toLowerCase().includes(metadataSearch.value.toLowerCase())&&(!metadataFavoritesOnly||x.favorite)&&(!metadataTagFilter||(x.tags||[]).some(tag=>tag.toLowerCase().includes(metadataTagFilter))))){const card=e('article',undefined,'metadata-library-card');if(item.image){const im=e('img');im.src=item.image;im.alt=item.name;im.loading='lazy';im.tabIndex=0;im.onclick=()=>metadataImageViewer(item);im.onkeydown=ev=>{if(ev.key==='Enter')metadataImageViewer(item);};card.append(im);}else{const placeholder=e('div','旧记录未保存原图','meta-missing');card.append(placeholder,uploadButton('补充预览原图',async file=>{await updateMetadataEntry(item.id,{image:'data:'+file.type+';base64,'+await blobBase64(file)});},'image/png,image/jpeg,image/webp'));}const favorite=b(item.favorite?'★':'☆',()=>updateMetadataEntry(item.id,{favorite:!item.favorite}));favorite.className='gallery-favorite';favorite.setAttribute('aria-label',item.favorite?'取消收藏':'收藏');card.append(favorite,e('strong',item.name),e('p',(item.tags||[]).map(t=>'#'+t).join(' '),'meta-tags'),row(b('复制所选',()=>copyMetadataSelection(item)),b('抓取 / 导入',()=>showMetadata(copy(item.data),item.warnings||[]))),row(b('改名 / 标签',()=>editMetadataEntry(item)),b('删除',()=>{const {dialog,close}=modal('删除这条元数据？');dialog.append(e('p',item.name+(item.favorite?'（已收藏）':'')),b('确认删除',async()=>{await dbOp('metadata','delete',item.id);close();await renderMetadataLibrary();}));})));metadataLibraryList.append(card);}if(!metadataLibraryList.children.length)note(metadataLibraryList,'没有匹配的元数据图片。上传原始 PNG 后可按名字查找、打标签和收藏。');}


